SELECT 'dc34f184-b681-4ac6-8e7a-33cf39b11626', id, 0, 'send_messages', '{"messages":[{"messageType":"text","content":"【現在地の確認です】\n\nFurimAutoです。\n無料期間は残り5日になりました。\n\nいま、自分がどこまで来たか\n確認してみてください。\n\n✅ リサーチで売れるものが分かる（無料）\n✅ 出品まわりの補助機能（無料）\n⬜ 値下げ・再出品などの自動化（無料期間中に体験できます）\n⬜ コピー出品での販路拡大\n⬜ 併売の在庫管理\n\n正直にお伝えすると、\n基本のリサーチと出品まわりの機能は\n期間が終わっても無料のまま使えます。\n\n有料になるのは「自動化」から先です。\n\n残り5日。まだ試していない自動化があれば、\n今のうちに動かしてみてください。\n\n「使い方がよく分からない…」という方は、\n【Youtube動画講座】が近道です🎬\n入門から上級まで、段階的に理解できます。\n\n▼ 再生リストはこちら\nhttps://youtube.com/playlist?list=PLUhATsy78sfvUHMVmeQpKMyxATlHOCEeF&si=4ZT_HFKCIGcuHibG\n\n\"手放せるかどうか\"は、\n体験した人にしか分かりません。"}]}', '{"remaining_days_gte":5,"remaining_days_lte":5}', 1, '残5日: 現在地の確認（v2）', datetime('now', '+9 hours'), datetime('now', '+9 hours')
FROM automations WHERE event_type = 'closing_daily' LIMIT 1;
