SELECT 'fbe1e8ca-d32d-450d-868d-63a754be91d2', id, 1, 'send_messages', '{"messages":[{"messageType":"text","content":"【時給換算、してみませんか】\n\n毎日の値下げ・コメント・取引メッセージ。\n仮に1日30分なら、1ヶ月で約15時間です。\n\n時給1,000円で換算すると、月15,000円ぶん。\n\nFurimAutoの自動化は\n最安480円/月〜から始められます。\n\nそして、いちばんお得に始める方法がこちら🎁\n\nリッチメニューの【Youtube動画講座】を見て、\n動画内で案内されるキーワードを\nこのLINEに送ってください。\n\nFurimAutoの\"全自動化\"を理解できるうえに、\n初回決済で使える割引クーポンが届きます👇"},{"messageType":"image","content":"{\"originalContentUrl\":\"https://storage.googleapis.com/furimauto_line/images/messageEvent/youtube_coupon.png\",\"previewImageUrl\":\"https://storage.googleapis.com/furimauto_line/images/messageEvent/youtube_coupon.png\"}"},{"messageType":"text","content":"【お得に使えるクーポンをGET!!】\n\n動画内のキーワードをLINEに送っていただいた方には、\n\n・友達登録から1週間以内 → 月額半額クーポン\n・それ以外 → 月額20%引きクーポン\n\nをそれぞれプレゼントいたします！"},{"messageType":"flex","altText":"あなたに最適なプランを1分診断","content":"{\"type\":\"bubble\",\"body\":{\"type\":\"box\",\"layout\":\"vertical\",\"contents\":[{\"type\":\"text\",\"text\":\"あなたに最適なプランを1分診断\",\"weight\":\"bold\",\"size\":\"md\",\"wrap\":true,\"color\":\"#D94A3D\"},{\"type\":\"text\",\"text\":\"使い方に合ったプランと料金がその場でわかり、割引クーポンも使ってそのまま登録できます。\",\"size\":\"sm\",\"color\":\"#666666\",\"wrap\":true,\"margin\":\"md\"}]},\"footer\":{\"type\":\"box\",\"layout\":\"vertical\",\"spacing\":\"sm\",\"contents\":[{\"type\":\"button\",\"style\":\"primary\",\"color\":\"#D94A3D\",\"height\":\"sm\",\"action\":{\"type\":\"uri\",\"label\":\"プラン診断をはじめる\",\"uri\":\"https://liff.line.me/1660804123-ZfTZnrBV\"}}]}}"}]}', '{"remaining_days_gte":3,"remaining_days_lte":3}', 1, '残3日: 時給換算＋Youtube動画講座→クーポン（v2）', datetime('now', '+9 hours'), datetime('now', '+9 hours')
FROM automations WHERE event_type = 'closing_daily' LIMIT 1;
