SELECT '8896e7ec-3724-4268-8d80-c3644620c310', id, 2, 'send_messages', '{"messages":[{"messageType":"text","content":"【登録は、思っているより簡単です】\n\n「手続きが面倒そう」と\n思っていませんか？\n\nFurimAutoの登録に、\n説明会や面談はありません。\n\n① プラン診断で自分に合うプランを確認（1分）\n② そのまま画面から申し込み\n③ クレジットカード決済で完了\n\nこれだけです。最短3分で、\nいま体験中の自動化がそのまま続きます。\n\n無料期間は残り2日。\nプラン選びに迷ったら、\nこのLINEにそのまま返信してください😊"},{"messageType":"flex","altText":"あなたに最適なプランを1分診断","content":"{\"type\":\"bubble\",\"body\":{\"type\":\"box\",\"layout\":\"vertical\",\"contents\":[{\"type\":\"text\",\"text\":\"あなたに最適なプランを1分診断\",\"weight\":\"bold\",\"size\":\"md\",\"wrap\":true,\"color\":\"#D94A3D\"},{\"type\":\"text\",\"text\":\"使い方に合ったプランと料金がその場でわかり、割引クーポンも使ってそのまま登録できます。\",\"size\":\"sm\",\"color\":\"#666666\",\"wrap\":true,\"margin\":\"md\"}]},\"footer\":{\"type\":\"box\",\"layout\":\"vertical\",\"spacing\":\"sm\",\"contents\":[{\"type\":\"button\",\"style\":\"primary\",\"color\":\"#D94A3D\",\"height\":\"sm\",\"action\":{\"type\":\"uri\",\"label\":\"プラン診断をはじめる\",\"uri\":\"https://liff.line.me/1660804123-ZfTZnrBV\"}}]}}"}]}', '{"remaining_days_gte":2,"remaining_days_lte":2}', 1, '残2日: 登録は簡単（v2）', datetime('now', '+9 hours'), datetime('now', '+9 hours')
FROM automations WHERE event_type = 'closing_daily' LIMIT 1;
