SELECT '678455d0-10e5-4dc9-9b98-04975eb03235', id, 3, 'send_messages', '{"messages":[{"messageType":"text","content":"【本日で無料期間が終了します】\n\nFurimAutoです。\n\n明日以降、キーコードが無効になり、\n設定済みの自動化（値下げ・再出品・\nいいね対応など）は停止します。\n\nただ、ご安心ください。\nリサーチなどの無料機能は\nこれからも、ずっと使えます。\n\nそのうえで──\n\nこの1週間で\n「もう手作業には戻りたくない」\nと感じたなら、それが答えだと思います。\n\n登録はプラン診断から最短3分。\n割引クーポンがまだの方は、\n動画内で案内されるキーワードを\n送るだけで受け取れます。\n\n▼ 完全解説動画はこちら\nhttps://youtu.be/jhaCPxgE_Sk\n\n最後にもう一度だけ、\n背中を押させてください👇"},{"messageType":"flex","altText":"あなたに最適なプランを1分診断","content":"{\"type\":\"bubble\",\"body\":{\"type\":\"box\",\"layout\":\"vertical\",\"contents\":[{\"type\":\"text\",\"text\":\"あなたに最適なプランを1分診断\",\"weight\":\"bold\",\"size\":\"md\",\"wrap\":true,\"color\":\"#D94A3D\"},{\"type\":\"text\",\"text\":\"使い方に合ったプランと料金がその場でわかり、割引クーポンも使ってそのまま登録できます。\",\"size\":\"sm\",\"color\":\"#666666\",\"wrap\":true,\"margin\":\"md\"}]},\"footer\":{\"type\":\"box\",\"layout\":\"vertical\",\"spacing\":\"sm\",\"contents\":[{\"type\":\"button\",\"style\":\"primary\",\"color\":\"#D94A3D\",\"height\":\"sm\",\"action\":{\"type\":\"uri\",\"label\":\"プラン診断をはじめる\",\"uri\":\"https://liff.line.me/1660804123-ZfTZnrBV\"}}]}}"}]}', '{"remaining_days_gte":1,"remaining_days_lte":1}', 1, '残1日: 本日で無料期間終了（v2）', datetime('now', '+9 hours'), datetime('now', '+9 hours')
FROM automations WHERE event_type = 'closing_daily' LIMIT 1;
